      "id": "nasa-stakes-ten-billion-dollars-lunar-infrastructure",
      "title": "NASA Stakes Ten Billion Dollars on Lunar Infrastructure Contracts",
      "kicker": "SCIENCE // SPACE EXPLORATION",
      "category": "science",
      "subtopic": "authors",
      "author": "Dr. Aris Thorne",
      "role": "Staff Writer",
